// ExecutePendingInvokes starts deferred child state machines (W3C SCXML 6.4).
// Port of Rust do_execute_pending_invokes().
func (p *StaticInvokeTreePolicy) ExecutePendingInvokes(engine *sce.Engine[StaticInvokeTreeState, StaticInvokeTreeEvent]) {
	if len(p.pendingInvokes) == 0 {
		return
	}

	// W3C SCXML 6.4: Copy-and-clear to prevent iterator invalidation
	invokesToExecute := make([]sce.PendingInvoke[StaticInvokeTreeState], len(p.pendingInvokes))
	copy(invokesToExecute, p.pendingInvokes)
	p.pendingInvokes = p.pendingInvokes[:0]

	for _, pending := range invokesToExecute {
		if pending.DocumentID == "worker" {


			// W3C SCXML 6.5: Generate child session ID for finalize origin matching
			childSessionID := fmt.Sprintf("%s.%s", p.SessionID, pending.InvokeID)

			// W3C SCXML 6.4: Create child state machine
			childPolicy := NewStaticInvokeTreeSceSynthInvokeWorkerPolicy()
			childPolicy.ParentExternalQueue = sce.NewParentEventQueue()
			childPolicy.InvokeID = pending.InvokeID
			childPolicy.ChildSessionID = childSessionID
			// W3C SCXML C.1: the child adopts the id its parent recorded for
			// it. The parent mints `parentSession.invokeId` and keys
			// `activeInvokes` on it, so an event from this child reaches the
			// parent carrying that id as its origin; if the child also minted
			// an id of its own, the location it publishes in `_ioprocessors`
			// and the origin the parent sees would be two names for one
			// session that can never be compared — which is exactly what C.1
			// requires of them.
			childPolicy.SessionID = childSessionID



			// W3C SCXML 6.4.1: Track active invoke session BEFORE initialize
			p.activeInvokes["worker"] = &sce.ChildSession{
				SessionID:       childSessionID,
				InvokeID:        "worker",
				ParentSessionID: p.SessionID,
				Autoforward:     true,
				FinalizeScript:  "",
			}

			childEngine := sce.NewEngine[StaticInvokeTreeSceSynthInvokeWorkerState, StaticInvokeTreeSceSynthInvokeWorkerEvent](&childPolicy)
			// §scxml-6.4: the child's delayed sends are measured against the
			// same clock as ours. A child reading its own would start its
			// origin at construction time, so <send delay="100ms"> on either
			// side of the boundary would mean two different absolute instants —
			// and on a host-owned clock the child would not move at all,
			// because the host advances the engine it holds, not the ones that
			// engine invoked.
			childEngine.SetClock(engine.Clock())
			// docs/adr/0045: the tree's host invokers serve the child, whose host-run
			// invocations name it by its session id.
			engine.ShareHostInvokersWith(childEngine)
			childEngine.SetCompletionCallback(func() {})
			// Child sessions in Mesh (SCE_MESH.md): the child's router, asked of
			// this machine's factory with the invoke's id and the stem of the
			// child's document (empty for one written inline), and installed
			// before the child initializes, since its first <onentry> may
			// already send to a peer.
			engine.StartChildMesh(childEngine, "worker", "")
			childEngine.Initialize()

			// W3C SCXML 6.4: Store child and create wrapper
			wrapper := &childEngineWrapperStaticInvokeTree_Worker{engine: childEngine, policy: &childPolicy}
			p.childWorker = wrapper

			// W3C SCXML 6.4: Drain child-to-parent events raised during initialize
			sce.DrainAndRaiseChildEvents(wrapper, p.activeInvokes, "worker", engine)

			// W3C SCXML 6.4: Check if child completed during initialize
			if wrapper.IsInFinalState() {
				p.pendingDoneInvokeWorker = true
				// The session ended: its Mesh router is told so.
				wrapper.DetachMesh()
				// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
				// done.invoke.<id>._event.data. Mirrors the C++ AOT contract
				// and the Rust raise_done_invoke(donedata) 3-arg signature.
				sce.RaiseDoneInvoke("worker", wrapper.DonedataAtFinal(), engine)
			}
			continue
		}
	}
}

// TickChildren ticks child state machines (W3C SCXML 6.4).
// Port of Rust do_tick_children().
func (p *StaticInvokeTreePolicy) TickChildren(engine *sce.Engine[StaticInvokeTreeState, StaticInvokeTreeEvent]) {
	if !p.pendingDoneInvokeWorker && p.childWorker != nil {
		child := p.childWorker
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "worker", engine)
		// Child sessions in Mesh (SCE_MESH.md): what arrived for the child on
		// the router it was given, before its macrostep.
		child.ApplyMeshCalls()
		child.Tick()
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "worker", engine)
		if child.IsInFinalState() && !p.pendingDoneInvokeWorker {
			p.pendingDoneInvokeWorker = true
			// The session ended: its Mesh router is told so.
			child.DetachMesh()
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("worker", child.DonedataAtFinal(), engine)
		}
	}
}

// SettleChildren settles what every running child sent this machine while it was
// driven by a delivery (sce.ChildSettler; docs/adr/0045): the events it sent
// `#_parent` are raised here, and a child that reached its final state raises
// `done.invoke` once. One body for every drive of a child, so a save at any
// boundary of this session finds the child's buffer empty.
func (p *StaticInvokeTreePolicy) SettleChildren(engine *sce.Engine[StaticInvokeTreeState, StaticInvokeTreeEvent]) {
	if child := p.childWorker; child != nil && !p.pendingDoneInvokeWorker {
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "worker", engine)
		if child.IsInFinalState() {
			p.pendingDoneInvokeWorker = true
			// The session ended: its Mesh router is told so.
			child.DetachMesh()
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("worker", child.DonedataAtFinal(), engine)
		}
	}
}

// AdoptHostInvokersInChildren hands the tree's host invokers on to every child
// this machine holds now (sce.HostInvokeChildren; docs/adr/0045): a child a
// restore resumed holds children of its own, resumed with it before its parent
// could hand it anything.
func (p *StaticInvokeTreePolicy) AdoptHostInvokersInChildren(invokers *sce.TreeInvokers) {
	if tree, ok := p.childWorker.(sce.HostInvokeTree); ok {
		tree.AdoptHostInvokers(invokers)
	}
}

// RouteHostInvokeEndToChild delivers the ending of a host-run invocation to the
// child at or below which the session sessionID is (sce.HostInvokeChildren), and
// answers false when no running child holds it.
func (p *StaticInvokeTreePolicy) RouteHostInvokeEndToChild(sessionID string, ending sce.HostInvokeEnding) (bool, error) {
	if tree, ok := p.childWorker.(sce.HostInvokeTree); ok {
		if routed, err := tree.RouteHostInvokeEnd(sessionID, ending); routed {
			return true, err
		}
	}
	return false, nil
}

// NextChildDeadline reports the nearest deadline among the running children
// (W3C SCXML 6.4), so a host that walks time by TimeUntilNextScheduled does not
// step over a timer a child armed. The ticking above is what makes it this
// machine's. A child that has ended (pendingDoneInvoke) is skipped: the policy
// keeps it until its state exits, and what it armed is no longer owed.
func (p *StaticInvokeTreePolicy) NextChildDeadline() (time.Duration, bool) {
	var soonest time.Duration
	found := false
	if !p.pendingDoneInvokeWorker && p.childWorker != nil {
		if due, ok := p.childWorker.TimeUntilNextScheduled(); ok && (!found || due < soonest) {
			soonest, found = due, true
		}
	}
	return soonest, found
}

// ForwardToAutoforwardChildren forwards external events to children with autoforward=true (W3C SCXML 6.4.1).
//
// W3C 6.4 requires an exact copy, so the source event's metadata is forwarded
// with the name: the child must observe the same _event.data, _event.origin,
// _event.sendid, _event.origintype and _event.invokeid the parent observed.
//
// The event's name is not consulted. W3C SCXML Appendix D mainEventLoop
// forwards whatever it dequeued from the external queue, and 6.4.2 has
// `done.invoke.<id>` returned onto that queue, so a sibling invoke still
// running must see it. Internal-queue events — `error.*` (3.12.2) and
// `done.state.<id>` (3.7) — stay out of the forwarded set because this
// method is reached only from the external drain, not because of how they
// are spelled.
func (p *StaticInvokeTreePolicy) ForwardToAutoforwardChildren(eventName string, metadata sce.EventMetadata, engine *sce.Engine[StaticInvokeTreeState, StaticInvokeTreeEvent]) {
	if cs, ok := p.activeInvokes["worker"]; ok && cs.Autoforward {
		if p.childWorker != nil {
			p.childWorker.RaiseExternalByNameWithMeta(eventName, metadata)
		}
	}
}

// DeliverToInvocation delivers a delayed `<send target="#_<invokeid>">` whose
// wait is over, by name — a child need not declare every event its parent
// sends (W3C SCXML 6.2 + 6.4). It answers whether the invocation was there to
// take it: one whose session has reached its final state has ended, and the
// engine reports the send it could not deliver (W3C SCXML C.1).
func (p *StaticInvokeTreePolicy) DeliverToInvocation(invokeID, eventName, eventData, sendID string) bool {
	if invokeID == "worker" {
		if child := p.childWorker; child != nil && !child.IsInFinalState() {
			sce.DeliverToChild(child, eventName, eventData)
			return true
		}
		return false
	}
	return false
}

// IsInvocationRunning reports whether `#_<invokeid>` names an invocation running
// now (W3C SCXML 6.4 + C.1) — one whose session has reached its final state has
// ended, and a send naming it is reported when it is made.
func (p *StaticInvokeTreePolicy) IsInvocationRunning(invokeID string) bool {
	if invokeID == "worker" {
		child := p.childWorker
		return child != nil && !child.IsInFinalState()
	}
	return false
}

// IsChildSessionRunning reports whether a session id names a child of this
// machine that is running now (W3C SCXML C.1) — the test DeliverToChildSession
// makes.
func (p *StaticInvokeTreePolicy) IsChildSessionRunning(childSessionID string) bool {
	if childSessionID == "" {
		return false
	}
	if cs, ok := p.activeInvokes["worker"]; ok && cs.SessionID == childSessionID {
		child := p.childWorker
		return child != nil && !child.IsInFinalState()
	}
	return false
}

// DeliverToChildSession delivers an event addressed to a child's published
// location (W3C SCXML C.1).
//
// The parent mints `parentSession.invokeId` for each child and that id is what
// the child's `_ioprocessors` entry names, so a <send> whose target decodes to
// one of them is addressed to that child rather than to this machine. A false
// return means the address names no live child of ours and the event takes the
// normal external path — the routing half of C.1 is what makes the published
// location a usable target rather than a string that merely compares equal.
func (p *StaticInvokeTreePolicy) DeliverToChildSession(childSessionID, eventName, eventData string) bool {
	if !p.IsChildSessionRunning(childSessionID) {
		return false
	}
	if cs, ok := p.activeInvokes["worker"]; ok && cs.SessionID == childSessionID {
		sce.DeliverToChild(p.childWorker, eventName, eventData)
		return true
	}
	return false
}


